const openAskedQuestionsForRun = `-- name: OpenAskedQuestionsForRun :many
UPDATE questions
SET state = 'open', opened_at = now()
WHERE org_id = $1 AND run_id = $2 AND state = 'asked'
RETURNING org_id, id, task_id, run_id, agent_id, asked_to, question, choices, draft, default_answer, state, answer, answer_kind, answered_by, call_sha256, expires_at, opened_at, notified_at, notify_failures, resolved_at, delivered_at, created_at, updated_at
`

type OpenAskedQuestionsForRunParams struct {
	OrgID pgtype.UUID
	RunID pgtype.UUID
}

// The turn ended: the run's asked questions become visible. Called in the transaction that parks
// the run.
func (q *Queries) OpenAskedQuestionsForRun(ctx context.Context, arg OpenAskedQuestionsForRunParams) ([]Question, error) {
	rows, err := q.db.Query(ctx, openAskedQuestionsForRun, arg.OrgID, arg.RunID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Question
	for rows.Next() {
		var i Question
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.TaskID,
			&i.RunID,
			&i.AgentID,
			&i.AskedTo,
			&i.Question,
			&i.Choices,
			&i.Draft,
			&i.DefaultAnswer,
			&i.State,
			&i.Answer,
			&i.AnswerKind,
			&i.AnsweredBy,
			&i.CallSha256,
			&i.ExpiresAt,
			&i.OpenedAt,
			&i.NotifiedAt,
			&i.NotifyFailures,
			&i.ResolvedAt,
			&i.DeliveredAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recordQuestionNotifyFailure = `-- name: RecordQuestionNotifyFailure :one
UPDATE questions
SET notify_failures = notify_failures + 1,
    notified_at = CASE WHEN notify_failures + 1 >= $1::int THEN now() ELSE notified_at END
WHERE org_id = $2 AND id = $3 AND notified_at IS NULL
RETURNING org_id, id, task_id, run_id, agent_id, asked_to, question, choices, draft, default_answer, state, answer, answer_kind, answered_by, call_sha256, expires_at, opened_at, notified_at, notify_failures, resolved_at, delivered_at, created_at, updated_at
`

type RecordQuestionNotifyFailureParams struct {
	GiveUp int32
	OrgID  pgtype.UUID
	ID     pgtype.UUID
}

// One failed delivery of the notification. At @give_up failures the question counts as notified
// (notified_at is set), so the sweep stops re-sending it; the caller logs that it gave up.
func (q *Queries) RecordQuestionNotifyFailure(ctx context.Context, arg RecordQuestionNotifyFailureParams) (Question, error) {
	row := q.db.QueryRow(ctx, recordQuestionNotifyFailure, arg.GiveUp, arg.OrgID, arg.ID)
	var i Question
	err := row.Scan(
		&i.OrgID,
		&i.ID,
		&i.TaskID,
		&i.RunID,
		&i.AgentID,
		&i.AskedTo,
		&i.Question,
		&i.Choices,
		&i.Draft,
		&i.DefaultAnswer,
		&i.State,
		&i.Answer,
		&i.AnswerKind,
		&i.AnsweredBy,
		&i.CallSha256,
		&i.ExpiresAt,
		&i.OpenedAt,
		&i.NotifiedAt,
		&i.NotifyFailures,
		&i.ResolvedAt,
		&i.DeliveredAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const resolveQuestion = `-- name: ResolveQuestion :one
UPDATE questions
SET state = $1::question_state,
    answer = $2,
    answer_kind = $3::question_answer_kind,
    answered_by = $4,
    resolved_at = now()
WHERE org_id = $5 AND id = $6 AND state = 'open'
RETURNING org_id, id, task_id, run_id, agent_id, asked_to, question, choices, draft, default_answer, state, answer, answer_kind, answered_by, call_sha256, expires_at, opened_at, notified_at, notify_failures, resolved_at, delivered_at, created_at, updated_at
`

